with base as (select * from payments where method != 'promptpay' and paid_at < '2024-02-18'), PaidCohortSummary as (select case when year(paid_at) < 2024 then 'before_2024' when year(paid_at) = 2024 then '2024' else 'after_2024' end paid_cohort, count(amount) amount_count, sort_array(collect_set(method)) method_list from base group by case when year(paid_at) < 2024 then 'before_2024' when year(paid_at) = 2024 then '2024' else 'after_2024' end) select paid_cohort, amount_count, method_list from PaidCohortSummary;
